WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.ViewCount, p.Score, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST) AS Rank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), PostStatistics AS (SELECT p.OwnerUserId, COUNT(DISTINCT p.Id) AS TotalPosts, SUM(CASE WHEN p.Score > 0 THEN 1 ELSE 0 END) AS PositivePosts, SUM(CASE WHEN p.Score < 0 THEN 1 ELSE 0 END) AS NegativePosts FROM Posts AS p JOIN Users AS u ON p.OwnerUserId = u.Id WHERE u.Reputation > 1000 GROUP BY p.OwnerUserId), UserBadges AS (SELECT u.Id AS UserId, GROUP_CONCAT(b.Name, ', ') AS Badges FROM Users AS u LEFT JOIN Badges AS b ON b.UserId = u.Id GROUP BY u.Id), CloseReasonStats AS (SELECT ph.PostId, COUNT(ph.Comment) AS CloseCount, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph LEFT JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.CreationDate, rp.ViewCount, rp.Score, ps.TotalPosts, ps.PositivePosts, ps.NegativePosts, ub.Badges, cr.CloseCount, cr.CloseReasons FROM RankedPosts AS rp LEFT JOIN PostStatistics AS ps ON rp.PostId = ps.OwnerUserId LEFT JOIN UserBadges AS ub ON ps.OwnerUserId = ub.UserId LEFT JOIN CloseReasonStats AS cr ON rp.PostId = cr.PostId WHERE rp.Rank = 1 ORDER BY rp.Score DESC NULLS FIRST LIMIT 100